import urllib.request, json, hashlib, tarfile, io, os

def sdist_urls(version):
    with urllib.request.urlopen(f'https://pypi.org/pypi/Django/{version}/json', timeout=30) as r:
        data = json.load(r)
    for f in data['urls']:
        if f['packagetype'] == 'sdist':
            return f['url']
    return None

def get_tests_hash(version):
    url = sdist_urls(version)
    if not url:
        return None, None
    with urllib.request.urlopen(url, timeout=60) as r:
        blob = r.read()
    tf = tarfile.open(fileobj=io.BytesIO(blob))
    member = [m for m in tf.getnames() if m.endswith('tests/mail/tests.py')]
    if not member:
        return None, None
    content = tf.extractfile(member[0]).read()
    return len(content), hashlib.sha256(content).hexdigest()

